-- Add the single-video purpose without changing any published image identity.
ALTER TABLE generation_plans DROP CONSTRAINT generation_plans_input_check;
ALTER TABLE generation_plans DROP CONSTRAINT generation_plans_check;
ALTER TABLE generation_plans ADD CHECK((input->>'scope'='project' AND (input->>'projectId')::uuid=project_id AND input->>'purpose' IN ('script_analysis','creative_assistance','image','video')) IS TRUE);
ALTER TABLE generation_plans ADD CHECK(((input->>'purpose'='script_analysis' AND input->'proposalTarget'->>'mode'='append_to_scene') OR (input->>'purpose'='creative_assistance' AND input->'assistance'->>'kind'='prepare_prompt' AND jsonb_array_length(input->'shotSources') BETWEEN 1 AND 100) OR (input->>'purpose' IN ('image','video'))) IS TRUE);
ALTER TABLE generation_media_outputs DROP CONSTRAINT generation_media_outputs_source_check;
ALTER TABLE generation_media_outputs DROP CONSTRAINT generated_source_complete;
ALTER TABLE generation_media_outputs ADD CONSTRAINT generated_source_complete CHECK((source->>'kind'='fixture_object' AND jsonb_typeof(source->'object')='object' AND source->'object'->>'key' ~ '^(staging|originals)/[a-f0-9-]{36}$' AND source->>'sha256' ~ '^[a-f0-9]{64}$' AND source->>'mime' IN ('image/png','image/jpeg','image/webp','video/mp4') AND (source->'object'->>'bytes')::bigint BETWEEN 1 AND 268435456 AND length(source->'object'->>'versionId') BETWEEN 1 AND 1024 AND source->'object'->>'versionId'<>'null' AND jsonb_typeof(output_options)='object' AND output_options->>'resolution' ~ '^[0-9]+x[0-9]+$' AND (source->>'mime'<>'video/mp4' OR ((output_options->>'durationSeconds')::integer BETWEEN 1 AND 7200 AND jsonb_typeof(output_options->'withAudio')='boolean'))) IS TRUE);
